"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["29429"],{79719(e){e.exports=JSON.parse('{"id":"FIN-415","slug":"exit-multiple-method","term":"Exit Multiple Method","also_known_as":[],"difficulty":"Intermediate","definition":"The exit multiple method calculates a company\'s terminal value in a discounted cash flow model by applying a valuation multiple, such as EV/EBITDA, to a financial measure in the final forecast year.","explanation":["Instead of assuming growth continues forever, the exit multiple method estimates what the business could be sold for at the end of the forecast period, based on how similar companies are currently valued.","For example, if a company\'s EBITDA in year five is forecast to be 100 million and comparable companies trade at 8 times EBITDA, the terminal value at the end of year five is 800 million. Discounted at 10% a year, that is worth about 497 million today.","The method is popular with practitioners, especially in mergers and acquisitions and private equity, because it reflects how buyers actually price businesses in the market.","Its main weakness is that it brings current market valuations into what should be a long-term, cash-based analysis. If markets are unusually optimistic or pessimistic today, the terminal value will be too. The choice of multiple also requires judgment, since the company may look different in five years from its peers today. Analysts often compare the result with the perpetual growth method to check whether the two give consistent values."],"note":"","total":1500,"prev":{"slug":"exercise","term":"Exercise"},"next":{"slug":"exit-strategy","term":"Exit Strategy"}}')}}]);